workflow.input_script:
function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return [];
  return [value];
}
var owners = toArray(input.owner);
var names = toArray(input.name);
if (!owners.length || !names.length || owners.length !== names.length) {
  throw new Error('owner and name must be non-empty arrays of equal length');
}
var repoIds = [];
var seen = {};
for (var i = 0; i < owners.length; i++) {
  var owner = String(owners[i] == null ? '' : owners[i]).trim();
  var name = String(names[i] == null ? '' : names[i]).trim();
  if (!owner || !name) throw new Error('owner and name values must not be empty');
  var id = owner.replace(/\//g, ':') + '/' + name;
  if (!seen[id]) { seen[id] = true; repoIds.push(id); }
}
var from = Number(input.from);
var to = Number(input.to);
if (!isFinite(from) || !isFinite(to) || from < 0 || to < from) {
  throw new Error('valid from and to Unix timestamps are required');
}
var rawBlueprints = toArray(input.blueprintid);
var blueprintIds = [];
for (var j = 0; j < rawBlueprints.length; j++) {
  var idNumber = Number(rawBlueprints[j]);
  if (!isFinite(idNumber) || idNumber <= 0 || Math.floor(idNumber) !== idNumber) {
    throw new Error('blueprintid must contain positive integers');
  }
  blueprintIds.push(idNumber);
}
({ repo_ids: repoIds, from: from, to: to,
   blueprint_ids: blueprintIds.length ? blueprintIds : [-1],
   has_blueprint: blueprintIds.length ? 1 : 0 })

workflow.output_script:
function byRepo(rows) {
  var map = {};
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i] || {};
    if (row.repo_id && !map[row.repo_id]) map[row.repo_id] = row;
  }
  var values = [];
  for (var id in map) if (Object.prototype.hasOwnProperty.call(map, id)) values.push(map[id]);
  return values;
}
function round1(value) { return Math.round(value * 10) / 10; }
var coverage = byRepo(results.coverage_summary || []).filter(function (r) { return Number(r.total_coverage) > 0; });
if (!coverage.length) {
  ({ error: 'No code coverage data found for the selected repositories' });
} else {
  var patch = byRepo(results.patch_coverage || []).filter(function (r) { return r.avg_patch_coverage != null; });
  var goals = byRepo(results.coverage_goals || []);
  var avgCoverage = 0;
  var deltas = [];
  var latestUpdate = 0;
  for (var c = 0; c < coverage.length; c++) {
    var cov = coverage[c];
    avgCoverage += Number(cov.avg_coverage) || Number(cov.total_coverage);
    if (Number(cov.earliest_coverage) > 0) deltas.push(Number(cov.total_coverage) - Number(cov.earliest_coverage));
    latestUpdate = Math.max(latestUpdate, Number(cov.latest_update) || 0);
  }
  avgCoverage = round1(avgCoverage / coverage.length);
  var patchMetricValue = 'N/A';
  if (patch.length) {
    var patchSum = 0;
    for (var p = 0; p < patch.length; p++) patchSum += Number(patch[p].avg_patch_coverage);
    patchMetricValue = round1(patchSum / patch.length);
  }
  var avgDelta = 0;
  for (var d = 0; d < deltas.length; d++) avgDelta += deltas[d];
  if (deltas.length) avgDelta /= deltas.length;
  var trend = avgDelta > 1 ? '+' + round1(avgDelta) + '%' : avgDelta < -1 ? round1(avgDelta) + '%' : 'Stable';
  function resolveGoal(field, autoField) {
    var counts = {}, options = [];
    for (var i = 0; i < goals.length; i++) {
      var value = goals[i][autoField] ? 'auto' : goals[i][field];
      if (value == null) continue;
      var key = String(value);
      if (!counts[key]) { counts[key] = 0; options.push(key); }
      counts[key]++;
    }
    if (!options.length) return undefined;
    options.sort(function (a, b) { return counts[b] - counts[a]; });
    if (options.length > 1 && counts[options[0]] === counts[options[1]]) return undefined;
    return options[0] === 'auto' ? 'auto' : Number(options[0]);
  }
  function resolveInformational(field) {
    var values = [];
    for (var i = 0; i < goals.length; i++) {
      if (goals[i][field] != null) values.push(Boolean(goals[i][field]));
    }
    if (!values.length) return undefined;
    var all = values.every(function (v) { return v; });
    var some = values.some(function (v) { return v; });
    return all ? true : some ? undefined : false;
  }
  var coverageMetric = { label: 'Avg Coverage (%)', value: avgCoverage };
  var projectGoal = resolveGoal('project_target', 'project_target_auto');
  if (projectGoal !== undefined) {
    coverageMetric.goal = projectGoal;
    var projectInfo = resolveInformational('project_informational');
    if (projectInfo !== undefined) coverageMetric.informational = projectInfo;
  }
  var patchMetric = { label: 'Avg Patch Coverage (%)', value: patchMetricValue };
  var patchGoal = resolveGoal('patch_target', 'patch_target_auto');
  if (patchGoal !== undefined) {
    patchMetric.goal = patchGoal;
    var patchInfo = resolveInformational('patch_informational');
    if (patchInfo !== undefined) patchMetric.informational = patchInfo;
  }
  var metrics = [coverageMetric, patchMetric];
  var prs = results.pr_patch || [];
  var seenPr = {}, totalPrs = 0, bypassed = [], thresholds = {};
  for (var b = 0; b < prs.length; b++) {
    var pr = prs[b] || {};
    if (!pr.repo_id || pr.pr_number == null || pr.avg_patch == null) continue;
    var prKey = pr.repo_id + ':' + pr.pr_number;
    if (seenPr[prKey]) continue;
    seenPr[prKey] = true;
    totalPrs++;
    var threshold = pr.effective_threshold == null ? 80 : Number(pr.effective_threshold);
    thresholds[pr.repo_id] = threshold;
    if (Number(pr.avg_patch) < threshold) {
      bypassed.push({
        id: Number(pr.pr_number),
        url: pr.pr_url || 'https://github.com/' + pr.repo_id + '/pull/' + pr.pr_number,
        patch: Math.round(Number(pr.avg_patch) * 100) / 100
      });
    }
  }
  if (totalPrs) {
    var thresholdRepos = Object.keys(thresholds);
    var suffix = thresholdRepos.length === 1 ? ' < ' + thresholds[thresholdRepos[0]] + '%' : '';
    metrics.push({ label: 'Bypass Rate (%)', value: round1(100 * bypassed.length / totalPrs),
      explain: bypassed.length + '/' + totalPrs + ' PRs' + suffix });
  }
  metrics.push({ label: 'Trend', value: trend });
  var data = { metrics: metrics };
  if (bypassed.length) {
    bypassed.sort(function (a, b) { return a.patch - b.patch; });
    data.extra = {
      config: [{ location: 'appendToAnalytics', type: 'openList', field: 'bypassed',
        template: 'Show Bypassed PRs', labels: [
          { label: 'PR ID', field: 'id' }, { label: 'URL', field: 'url' },
          { label: 'Patch Coverage (%)', field: 'patch' }
        ] }],
      data: { bypassed: bypassed }
    };
  }
  var pipelineRows = results.last_pipeline || [];
  var pipelineUpdate = pipelineRows.length ? Number(pipelineRows[0].lastupdate) : 0;
  var output = {
    type: 'stats',
    label: 'Coverage Key Metrics',
    description: '<b>Avg Coverage</b> — mean overall coverage across tracked repos for the selected period (each repo weighted equally).<br><b>Avg Patch Coverage</b> — mean coverage of new or changed code in the period.<br><b>Target Bypass Rate</b> — percentage of merged PRs below the configured patch target (default 80%).<br><b>Trend</b> — average coverage change from start to end of period.',
    data: data
  };
  if (pipelineUpdate || latestUpdate) output.lastupdate = pipelineUpdate || latestUpdate;
  output;
}
